src = open('main.py').read()

# 1. Numeric literals: only the NaN/Infinity spellings are forbidden by the wire
#    format; ordinary JSON numbers (however large) reach the schema stage, where
#    every number is rejected.  Truncating keeps parsing cheap and lossless.
src = src.replace('''def _bad_constant(_name):
    raise ValueError('forbidden numeric constant')


def parse_json(text):
    return json.loads(text, object_pairs_hook=_pairs_hook,
                      parse_constant=_bad_constant)''',
'''def _bad_constant(_name):
    raise ValueError('forbidden numeric constant')


def _parse_int(text):
    # Numbers are never valid members of a request, so only the presence of a
    # value matters.  Truncating avoids interpreter digit limits and the cost
    # of building huge integers from hostile input.
    return int(text[:32]) if len(text) > 32 else int(text)


def _parse_float(_text):
    return 0.0


def parse_json(text):
    return json.loads(text, object_pairs_hook=_pairs_hook,
                      parse_constant=_bad_constant, parse_int=_parse_int,
                      parse_float=_parse_float)''')

# 2. The value scan now only has to check scalar validity of strings and keys.
src = src.replace('''def scan_values(root):
    """Check scalar validity of every string, key and number in the document."""
    bad_str = False
    bad_num = False
    stack = [root]
    while stack:
        node = stack.pop()
        kind = type(node)
        if kind is str:
            try:
                node.encode('utf-8')
            except UnicodeEncodeError:
                bad_str = True
        elif kind is list:
            if node:
                stack.extend(node)
        elif kind is dict:
            for key, value in node.items():
                try:
                    key.encode('utf-8')
                except UnicodeEncodeError:
                    bad_str = True
                stack.append(value)
        elif kind is float:
            if not math.isfinite(node):
                bad_num = True
    if bad_num:
        raise JsonError()
    if bad_str:
        raise SchemaError()''',
